from pathlib import Path
import json
R=Path.cwd();O=R/'build/graphics/arcade_review_r69';data=json.loads((O/'review_data.json').read_text());sha=json.loads((R/'build/graphics/arcade_rpc_comparison_r68/manifest.json').read_text())['rpc_sha256']
head='''<!doctype html><html><head><meta charset="utf-8"><title>R-Type artwork review</title><style>body{background:#15191f;color:#e9eef3;font:16px system-ui;margin:20px}header{position:sticky;top:0;z-index:4;background:#15191ff5;padding:12px;border-bottom:1px solid #657183}h1{margin:0}a{color:#85dfff}button,select,input,textarea{font:inherit}button{padding:7px;margin:4px}article{padding:20px;margin:20px 0;border:1px solid #52606d;border-radius:8px}article[hidden]{display:none}h2{margin:0}.warning{color:#ffd48a}.decisions{display:flex;gap:20px;flex-wrap:wrap;padding:12px;background:#26313c}.images{display:grid;grid-template-columns:1fr 1fr 1.4fr;gap:20px}.images img,.images canvas{image-rendering:pixelated;max-width:100%;min-width:64px;max-height:430px;object-fit:contain;background:black}canvas{image-rendering:pixelated;width:100%;max-width:750px;background:black}textarea{width:95%;height:46px;margin:10px 0}.controls{display:flex;gap:15px;flex-wrap:wrap;align-items:center;background:#222d38;padding:12px}.controls label{display:flex;gap:5px;align-items:center}.controls input[type=number]{width:65px}.controls input[type=range]{width:120px}details{margin:15px 0;padding:8px;border:1px solid #3f4d5b}summary{cursor:pointer}.familyMembers,.workState,#saveState{color:#8cdbbf}.mapView{width:min(512px,100%);height:320px;overflow:hidden;background:black}.mapView img{height:320px;max-width:none;image-rendering:pixelated}.motion{max-height:260px;object-fit:contain;width:auto;min-width:200px}.motionBox{margin-top:12px}details img{max-width:100%;image-rendering:pixelated}input[type=checkbox]{width:18px;height:18px}#search{max-width:200px}@media(max-width:850px){.images{grid-template-columns:1fr}header{position:static}}</style></head><body>
<header><h1>R-Type artwork review</h1><p>Choose one review checkbox per entry. Settings and size are shared by animation family. Live conversion uses the actual RPC CPU pipeline.</p><label>Level <select id="level"><option value="all">All</option>'''+''.join(f'<option>{i}</option>'for i in range(1,9))+'''</select></label> <select id="decisionFilter"><option value="all">All decisions</option><option value="unreviewed">Unreviewed</option><option value="accept">Accept</option><option value="tweak">Tweak settings</option><option value="review">Misidentified / needs review</option><option value="no-change">No change currently</option></select> <input id="search" placeholder="Find L3_101 or family"> <label><input id="stripsOnly" type="checkbox">Wide strips</label><button id="export">Export review JSON</button> <label>Import JSON <input id="import" type="file" accept="application/json,.json"></label><p><span id="shown"></span> · <span id="counts"></span></p><p><span id="saveState"></span> · <span id="busy">Ready</span></p></header>
<p>Review only: no playable artwork changes. Export JSON when finished so the choices and shared settings can be applied reliably. Browser autosave belongs to this local page/browser.</p><p>Wide-strip families start with the scrolling policy enabled; turn it off if the object is not scrolling terrain. Scrolling policy holds one normal-black/ink pair across each occupied horizontal run until a source gap of at least eight pixels. Vertical rows may use different colours. All eight horizontal phases are checked; texture is shifted, never re-dithered per phase. Source-match and animation grouping still need review where historical labels are uncertain.</p><main id="cards"></main>'''
def js(v):return json.dumps(v,separators=(',',':')).replace('<','\\u003c')
page=head+'<script>const DATA='+js(data)+';const WORKER_TEXT='+js((O/'worker.js').read_text(encoding='utf-8-sig'))+';const RPC_SHA='+js(sha)+';</script><script>'+(R/'src/art_review_r69.js').read_text(encoding='utf-8-sig')+'</script></body></html>'
(O/'index.html').write_text(page,encoding='utf-8');print('Review HTML bytes',len(page.encode()))
